api.example:
const w = atelier.widget({
  id: "hello",
  title: "Hello",
  refresh: 60,
  view: () => atelier.ui.text(new Date().toLocaleTimeString(), { size: 22, weight: "bold" }),
});

atelier.action("refresh", () => w.refresh());
// …
atelier.ui.button("Refresh", "refresh")

atelier.paletteProvider({
  title: "Emoji", prefix: "em",
  search: (q) => EMOJI.filter((e) => e.name.includes(q)).map((e) => ({ id: e.char, title: e.char + " " + e.name })),
  choose: (id) => console.log(id),
});

const a = atelier.liveActivity({ title: "Uploading", symbol: "arrow.up", progress: 0 });
// later
a.update({ progress: 0.5 });
a.end();
